window.S17Page={"sceneId":"t4","caseId":"s17x-t4-meter-drift-calibration","name":"油气计量智能校正","title":"油气计量校正：分清读数变化与仪表偏移","summary":"流量增长不一定是产量提高，也可能是流量计的比例偏差。利用独立标定点学出读数到参考流量的关系，再检查后续运行区间。","directory":"expansion-cases","caseVersion":"1.2.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){"use strict";function mean(a){return a.reduce((s,x)=>s+x,0)/a.length}function mae(a,b){return mean(a.map((v,i)=>Math.abs(v-b[i])))}function reg(x,y){let xm=mean(x),ym=mean(y);let b=x.reduce((s,v,i)=>s+(v-xm)*(y[i]-ym),0)/(x.reduce((s,v)=>s+(v-xm)**2,0)||1);return {a:ym-b*xm,b}}function median(a){a=a.slice().sort((x,y)=>x-y);return a[Math.floor(a.length/2)]}function rng(seed){return ()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296}}function run(p){let R=rng(424);let cal=Array.from({length:24},(_,i)=>{let ref=40+i*5;return{reference:ref,meter:ref*(1+p.gain/100)+2+(R()-.5)*p.noise*2}});let model=reg(cal.map(x=>x.meter),cal.map(x=>x.reference)),delta=mean(cal.map(x=>x.reference-x.meter));let refs=Array.from({length:60},(_,i)=>80+35*Math.sin(i/8)+i*.6);let meter=refs.map((v,i)=>v*(1+(p.gain+p.drift)/100)+2+(R()-.5)*p.noise*2);function predict(observations,m){return observations.map(x=>m.a+m.b*x)}let corrected=predict(meter,model),base=meter.map(x=>x+delta),volume=a=>a.reduce((s,x)=>s+x,0)/60,vol=volume(refs),err=a=>100*(volume(a)-vol)/vol;return{summary:'Q校正 = '+model.a.toFixed(3)+' + '+model.b.toFixed(5)+' × Q读数。系数只由前 24 个标定点拟合。',metrics:[['原始 MAE',mae(meter,refs).toFixed(2)+' m³/h'],['回归校正 MAE',mae(corrected,refs).toFixed(2)+' m³/h'],['平均差基线 MAE',mae(base,refs).toFixed(2)+' m³/h'],['校正累计偏差',err(corrected).toFixed(2)+'%']],charts:[{title:'24个独立标定点与拟合关系',xlabel:'被检表读数 m³/h',ylabel:'参考流量 m³/h',scatter:true,series:[{name:'标定点',x:cal.map(r=>r.meter),y:cal.map(r=>r.reference)},{name:'回归拟合线',line:true,x:[35,180],y:[35,180].map(v=>model.a+model.b*v)},{name:'y=x参考线',line:true,x:[35,180],y:[35,180]}]},{title:'60 分钟运行：读数、校正与独立参考',xlabel:'一分钟区间起点 min（0–59）',ylabel:'m³/h',series:[{name:'原始仪表',y:meter},{name:'回归校正',y:corrected},{name:'独立参考',y:refs},{name:'固定差基线',y:base}]}],headers:['方法','累计体积 m³','相对参考偏差 %'],rows:[['原始',volume(meter).toFixed(2),err(meter).toFixed(2)],['回归校正',volume(corrected).toFixed(2),err(corrected).toFixed(2)],['固定差基线',volume(base).toFixed(2),err(base).toFixed(2)],['独立参考',vol.toFixed(2),'0.00']],denominator:60,calibrationCount:24,calibration:cal,model,referenceUsedOnlyInEvaluation:true}};g.TransportEngine={run:run};})(globalThis);

